import re

def parse_date(s):
    m = re.fullmatch(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if not m:
        raise ValueError(s)
    return tuple(int(x) for x in m.groups())

def parse_date(s):
    parts = s.split('-')
    if len(parts) != 3:
        raise ValueError(s)
    y, m, d = parts
    if not (len(y) == 4 and 1 <= len(m) <= 2 and 1 <= len(d) <= 2):
        raise ValueError(s)
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        raise ValueError(s)
    return int(y), int(m), int(d)

