import re

def parse_date(s):
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', s) or re.fullmatch(r'(\d{4})-(\d)-(\d)', s)
    if not m:
        raise ValueError(s)
    return tuple(int(x) for x in m.groups())

import re

def parse_date(s):
    m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if not m:
        raise ValueError(s)
    return tuple(int(x) for x in m.groups())
